-- koloni-178: Tıslama (savunma) — Hz 500–20000, sadece kayıt, kaynak zayıf / ırka özgü, tam künyeler.
update public.ses_siniflari set hz_min = 500, hz_max = 20000, seviye = 'kayit',
  yapi = 'Geniş bant, harmonikli. A. m. cypria''da temel ~0,5 kHz, baskın ~5,9 kHz, 16–17 kHz''e kadar (eşek arısı saldırısı). A. mellifera''da laboratuvarda ~4–20 kHz (şok/koku). Tehdit tepkisi. Türkiye ırklarında ölçüm yok.',
  kaynak = 'Papachristoforou A., Sueur J., Rortais A., Angelopoulos S., Thrasyvoulou A., Arnold G. (2008). High frequency sounds produced by Cyprian honeybees Apis mellifera cypria when confronting their predator, the Oriental hornet Vespa orientalis. Apidologie 39(4):468–474. doi:10.1051/apido:2008027 · Wehmann H.-N., Gustav D., Kirkerud N.H., Galizia C.G. (2015). The Sound and the Fury—Bees Hiss when Expecting Danger. PLoS ONE 10(3):e0118708. doi:10.1371/journal.pone.0118708',
  kaynak_zayif = true, durum = 'kaynak zayıf / ırka özgü', updated_at = now()
where id = 'tislama';
